input.command:
$out = @()
foreach ($r in "$HOME\.claude","$HOME\.claude\skills","$HOME\.claude\global-memory") {
  Write-Output "=== $r"
  $before = git -C $r rev-parse HEAD
  if (git -C $r status --porcelain) { git -C $r add -A 2>&1 | Out-Null; git -C $r commit -q -m "windows snapshot before sync" 2>&1 | Select-Object -Last 2 }
  $pre = git -C $r rev-parse HEAD
  git -C $r pull --no-rebase --no-edit 2>&1 | Select-Object -Last 4
  $n = git -C $r rev-list --count "$pre..HEAD"
  Write-Output "incoming commits: $n"
  if ([int]$n -gt 0) { git -C $r log -1 --format="newest: %h %ad %s" --date=short }
  git -C $r push 2>&1 | Select-Object -Last 2
  git -C $r status -sb | Select-Object -First 1
}

