$root = 'C:\Users\eric_rash\Desktop\DEV'
$skip = '.claude','_tools','_DRIVE','token-dashboard'
$dirs = @()
foreach ($p in @($root, "$root\Football", "$root\SpecialRequests")) {
  if (-not (Test-Path $p)) { continue }
  Get-ChildItem -LiteralPath $p -Directory -Force | Where-Object {
    $skip -notcontains $_.Name -and $_.Name -notlike '*_OLD_merged*' -and
    -not ($p -eq $root -and ($_.Name -in 'Football','SpecialRequests' -and -not (Test-Path (Join-Path $_.FullName '.git'))))
  } | ForEach-Object { $dirs += $_ }
}
$rows = foreach ($d in $dirs) {
  $f = $d.FullName
  $rel = $f.Substring($root.Length+1)
  if (-not (Test-Path (Join-Path $f '.git'))) { [pscustomobject]@{Rel=$rel;State='NOREPO';Remote='';Dirty=0;Ahead=0;Branch=''}; continue }
  $remote = git -C $f remote get-url origin 2>$null
  if (-not $remote) { [pscustomobject]@{Rel=$rel;State='NOREMOTE';Remote='';Dirty=0;Ahead=0;Branch=''}; continue }
  $dirty = @(git -C $f status --porcelain 2>$null).Count
  $br = git -C $f rev-parse --abbrev-ref HEAD 2>$null
  $ahead = git -C $f rev-list --count "@{u}..HEAD" 2>$null
  if (-not $ahead) { $ahead = 'nou' }
  [pscustomobject]@{Rel=$rel;State=($(if ($remote -match 'erash11') {'OK'} else {'OTHERREMOTE'}));Remote=$remote;Dirty=$dirty;Ahead=$ahead;Branch=$br}
}
$rows | Export-Csv "$env:TEMP\..\inv_rows.csv" -NoTypeInformation -ErrorAction SilentlyContinue
$rows | Export-Csv 'C:\Users\eric_rash\.claude\jobs\5417a4eb\tmp\inv.csv' -NoTypeInformation
"total: $($rows.Count)"
$rows | Group-Object State | ForEach-Object { "$($_.Name): $($_.Count)" }
"--- non-clean / non-OK:"
$rows | Where-Object { $_.State -ne 'OK' -or $_.Dirty -gt 0 -or $_.Ahead -ne '0' -or $_.Branch -notin 'main','master' } | Format-Table Rel,State,Dirty,Ahead,Branch,Remote -AutoSize | Out-String -Width 250
# missing locally
$local = $rows | ForEach-Object { if ($_.Remote -match 'erash11/([^/]+?)(\.git)?$') { $Matches[1] } }
$localNames = $dirs | ForEach-Object { $_.Name }
$gh = (gh repo list erash11 --limit 300 --json name | ConvertFrom-Json).name
$skipGh = 'dotclaude','SecondBrain','claude-skills','claude-memory-compiler','DEV','DexaProject','claude-global-memory'
"--- gh repos: $($gh.Count); missing locally:"
$gh | Where-Object { $_ -notin $local -and $_ -notin $localNames -and $_ -notin $skipGh }

