input.content:
$rows = Import-Csv 'C:\Users\eric_rash\.claude\jobs\5417a4eb\tmp\inv.csv' | Where-Object State -eq 'OK'
$root = 'C:\Users\eric_rash\Desktop\DEV'
$res = foreach ($r in $rows) {
  $f = Join-Path $root $r.Rel
  $pre = git -C $f rev-parse HEAD
  $fe = git -C $f fetch origin 2>&1
  if ($LASTEXITCODE -ne 0) { [pscustomobject]@{Rel=$r.Rel;Result="FETCH-FAIL: $($fe | Select-Object -Last 1)"}; continue }
  $up = git -C $f rev-parse --abbrev-ref '@{u}' 2>$null
  if (-not $up) { $up = "origin/$($r.Branch)" }
  $behind = git -C $f rev-list --count "HEAD..$up" 2>$null
  if ([int]$behind -eq 0) { continue }
  $m = git -C $f merge --no-edit $up 2>&1
  if ($LASTEXITCODE -ne 0) { [pscustomobject]@{Rel=$r.Rel;Result="MERGE-FAIL: $($m | Select-Object -Last 3 | Out-String)"}; continue }
  $ahead = git -C $f rev-list --count "$up..HEAD"
  $push = ''
  if ([int]$ahead -gt 0) { $p = git -C $f push 2>&1; $push = if ($LASTEXITCODE) { " PUSH-FAIL: $($p|Select-Object -Last 1)" } else { " pushed $ahead" } }
  [pscustomobject]@{Rel=$r.Rel;Result="pulled $behind$push"}
}
"checked: $($rows.Count)"
$res | Format-Table -AutoSize | Out-String -Width 250

